1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"io/fs"
10		"os"
11		"sync"
12		"sync/atomic"
13	)
14	
15	// viewFlattenLimit bounds how deep an overlay chain a published view grows
16	// before the next commit builds it on a flattened copy. Without a bound the
17	// chain would gain one map per commit for the life of the store and memory
18	// would track cumulative commits; flattening every viewFlattenLimit commits
19	// keeps live depth (and the work a read or checkpoint walk does) independent
20	// of commit count, while the flattened copies stay immutable for every
21	// snapshot already holding an older view.
22	const viewFlattenLimit = 64
23	
24	// node is one immutable version in a key's history. Versions form a linked
25	// list from newest to oldest; a snapshot pins the head current when it was
26	// acquired, so overwritten and deleted values stay readable through every
27	// view that references them. seq is the version's commit number, unique and
28	// strictly increasing along each key's chain; it orders versions across the
29	// independent chains that meet again during a pinning compaction.
30	type node struct {
31		value   []byte
32		present bool   // false marks a delete; a present nil/empty value is still a hit
33		seq     uint64 // commit order, 1-based
34		older   *node
35	}
36	
37	// view is an immutable map of keys to their newest version. Rather than
38	// copying the whole map for every commit, a view is a thin overlay: its own
39	// keys on top of a base view it never modifies. Reads descend the short chain
40	// of overlays; the current view, snapshots and cursors simply point at one.
41	//
42	// A view's keys map may itself hold the whole keyspace: the base layer
43	// (base == nil) used by recovery, compaction and periodic flattening. Maps
44	// are never mutated after publication, so reading them needs no lock; only
45	// the commit path, which has just created a fresh overlay, writes its keys.
46	type view struct {
47		keys  map[string]*node
48		base  *view
49		depth int // number of overlays from this view to its flat base
50	}
51	
52	// newView returns an empty overlay atop base (nil for a flat base view).
53	func newView(base *view) *view {
54		d := 1
55		if base != nil {
56			d = base.depth + 1
57		}
58		return &view{keys: make(map[string]*node), base: base, depth: d}
59	}
60	
61	// lookup returns the newest version recorded for key anywhere along the
62	// overlay chain, or nil when the key was never written.
63	func (v *view) lookup(key string) *node {
64		for cur := v; cur != nil; cur = cur.base {
65			if n, ok := cur.keys[key]; ok {
66				return n
67			}
68		}
69		return nil
70	}
71	
72	// rangeEach visits the terminal version of every distinct key, fn once per
73	// key, walking newest-to-oldest so an overlay entry shadows its base.
74	func (v *view) rangeEach(fn func(key string, n *node) bool) {
75		seen := make(map[string]struct{})
76		for cur := v; cur != nil; cur = cur.base {
77			for k, n := range cur.keys {
78				if _, ok := seen[k]; ok {
79					continue
80				}
81				seen[k] = struct{}{}
82				if !fn(k, n) {
83					return
84				}
85			}
86		}
87	}
88	
89	// flatten materializes one flat map holding the view's complete terminal
90	// state. It allocates a fresh map and shares only immutable nodes, so views
91	// already published stay untouched.
92	func (v *view) flatten() *view {
93		flat := newView(nil)
94		v.rangeEach(func(k string, n *node) bool {
95			flat.keys[k] = n
96			return true
97		})
98		return flat
99	}
100	
101	// Store is an open key-value store backed by a directory on disk.
102	type Store struct {
103		mu sync.Mutex // serializes writers and guards the fields below
104	
105		dir       string
106		wal       *walWriter
107		current   atomic.Pointer[view] // latest committed view; lock-free for readers
108		snapshots atomic.Uint64        // cumulative number of snapshots handed out
109		nextSeq   uint64               // highest commit sequence handed out; guarded by mu
110	
111		// chain is the in-memory record of the usable checkpoint layers paired
112		// with the current WAL, oldest first. Empty means no checkpoint is live
113		// (the next Checkpoint writes a base). Compaction re-anchors it against
114		// the replacement log; Checkpoint appends a delta and prunes the window.
115		chain []layerState
116		// dirty keys were touched by effective commits strictly after the newest
117		// layer in chain; they are exactly the keys the next delta layer covers.
118		// nil until the first such commit.
119		dirty []string
120		// legacyLive reports that a version-1 single-file snapshot.ckpt was the
121		// checkpoint paired with the WAL at open and has not been replaced by a
122		// layered chain or retired by compaction. Compaction must durably retire
123		// it before swapping the WAL, exactly as it retires a layered chain.
124		legacyLive bool
125	
126		// Open cursors pin their fixed view's versions against compaction. The
127		// set is read by Compact (which holds mu) and mutated at cursor
128		// open/close, using cursorMu; reads never take either lock.
129		cursorMu sync.Mutex
130		cursors  map[*Cursor]struct{}
131	
132		// Group-commit queue. Every state-changing commit (single Put/Delete just
133		// like CommitBatch) that arrives while another commit is forcing the log
134		// lines up here; one leader drains the queue, encodes the waiting commits
135		// and shares a single flush plus fsync across them.
136		// queueMu only ever guards this queue and committer; it is never held
137		// across disk I/O, so readers and enqueuers never wait on a sync.
138		queueMu   sync.Mutex
139		queue     []*pendingBatch
140		committer bool
141	
142		// backupMu serializes exports that stage into one chain directory
143		// (BackupIncremental) so two exports on this store never share their
144		// staging directory. It is independent of mu: it is held across the
145		// export's disk I/O and never blocks commits or lock-free reads.
146		backupMu sync.Mutex
147	
148		// Test hook, nil outside tests. leaderHook runs once after a commit has
149		// become leader, before its first queue drain, and lets tests hold a
150		// leader until a known number of commits have coalesced.
151		leaderHook func()
152	
153		closed atomic.Bool
154	}
155	
156	// Snapshot is a stable read-only view of a store captured at one instant. It
157	// owns no store resources of its own and stays usable after the store has
158	// been closed; a cursor opened from it does register with the store while it
159	// pins versions.
160	type Snapshot struct {
161		v     atomic.Pointer[view] // nil once the snapshot is closed
162		store *Store               // back-reference for cursor pin accounting
163	}
164	
165	// Open opens or creates a persistent store in dir. A path that names a
166	// regular file rather than a directory returns an error wrapping
167	// fs.ErrInvalid.
168	func Open(dir string) (*Store, error) {
169		info, err := os.Stat(dir)
170		if err == nil {
171			if !info.IsDir() {
172				return nil, errNotDir
173			}
174		} else {
175			if !errors.Is(err, fs.ErrNotExist) {
176				return nil, err
177			}
178			if err := os.MkdirAll(dir, 0o700); err != nil {
179				return nil, err
180			}
181		}
182	
183		// A replacement log from a compaction killed before its rename can never
184		// be complete state of record; the old wal.log is. Drop the stale file.
185		// Likewise, staging debris from a kill mid-checkpoint (a half-built layer
186		// temp or a legacy single-file temp) is swept: only finished layers are
187		// ever read.
188		if err := removeStaleCompact(dir); err != nil {
189			return nil, err
190		}
191		if err := sweepCheckpointDebris(dir); err != nil {
192			return nil, err
193		}
194		if err := sweepStagedChain(dir); err != nil {
195			return nil, err
196		}
197		// Sweep debris from a hot backup that was killed before its manifest, and
198		// from a restore killed before its target rename. These names never appear
199		// in a live store, so a store that was merely backed up is unaffected.
200		if err := openBackupSweep(dir); err != nil {
201			return nil, err
202		}
203		sweepRestoreDebris(dir)
204		// Sweep sibling debris a chain merge killed mid-commit can leave next to
205		// a directory that was used as a backup chain.
206		sweepMergeDebris(dir)
207	
208		latest := newView(nil)
209		var replaySeq uint64
210		var snapshotCount uint64
211		var validSize int64
212		var chain []layerState
213		var tailTouched []string
214		var legacyLive bool
215	
216		// apply installs one replayed record into the latest view. Legacy
217		// records (written before sequence numbers existed) carry no seq; replay
218		// order is commit order, so number them sequentially.
219		apply := func(op byte, key string, value []byte, seq uint64) {
220			if seq == 0 {
221				replaySeq++
222				seq = replaySeq
223			} else if seq > replaySeq {
224				replaySeq = seq
225			}
226			switch op {
227			case opPut, opPutSeq:
228				latest.keys[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest.keys[key]}
229			case opDelete, opDeleteSeq:
230				latest.keys[key] = &node{present: false, seq: seq, older: latest.keys[key]}
231			}
232		}
233	
234		// Fast reopen: seed memory from the longest valid checkpoint-chain prefix
235		// and replay only the WAL written after its last layer. A layer is
236		// accepted only as a whole and only when it links to the layer before; a
237		// missing, truncated, checksum-bad, unknown-version or unlinked layer
238		// rejects it and every layer after it, and recovery falls back to the
239		// previous layer, to the legacy single-file checkpoint, or finally to a
240		// from-scratch WAL replay.
241		chainInfo, chainErr := readChain(dir)
242		if chainErr != nil {
243			return nil, chainErr
244		}
245		// Reject the suffix outright: anything beyond the longest intact, linked
246		// prefix is removed as a whole so a broken layer never pairs with the WAL
247		// and never occupies space. Half a layer is never installed.
248		pruneRejectedChainFiles(dir, len(chainInfo.layers))
249		walLen, sizeErr := walFileSize(dir)
250		if sizeErr != nil {
251			return nil, sizeErr
252		}
253		// The selected layer's cut must lie inside this exact WAL. Cuts are
254		// nondecreasing along the chain, so any suffix whose cut ran past the end
255		// of the file is rejected as a whole down to the last pairable layer.
256		for len(chainInfo.layers) > 0 && chainInfo.layers[len(chainInfo.layers)-1].offset > walLen {
257			removeRejectedChainSuffix(dir, chainInfo.layers[len(chainInfo.layers)-1].index)
258			chainInfo.layers = chainInfo.layers[:len(chainInfo.layers)-1]
259		}
260	
261		switch {
262		case len(chainInfo.layers) > 0:
263			// Compose the valid prefix: each layer overrides the one it builds on.
264			var last layerState
265			for _, l := range chainInfo.layers {
266				for _, e := range l.entries {
267					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
268				}
269				last = l
270			}
271			chain = chainInfo.layers
272			replaySeq = last.seq
273			// Replay the tail, remembering touched keys so the first delta layer
274			// taken in this opening also covers commits already past the cut.
275			tailApply := func(op byte, key string, value []byte, seq uint64) {
276				if op == opPut || op == opPutSeq || op == opDelete || op == opDeleteSeq {
277					tailTouched = append(tailTouched, key)
278				}
279				apply(op, key, value, seq)
280			}
281			var rerr error
282			validSize, snapshotCount, rerr = replayWALTail(dir, last.offset, last.snaps, tailApply)
283			if rerr != nil {
284				return nil, rerr
285			}
286		default:
287			// No layered chain: accept a legacy version-1 checkpoint if one is
288			// intact and pairs with this WAL, otherwise replay the whole log.
289			cp, cpOK, cpErr := loadLegacyCheckpoint(dir)
290			if cpErr != nil {
291				removeRejectedLegacy(dir)
292				cpOK = false
293			}
294			if cpOK && (cp.offset < 0 || cp.offset > walLen) {
295				removeRejectedLegacy(dir)
296				cpOK = false
297			}
298			if cpOK {
299				legacyLive = true
300				for _, e := range cp.entries {
301					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
302				}
303				replaySeq = cp.seq
304				validSize, snapshotCount, err = replayWALTail(dir, cp.offset, cp.snaps, apply)
305				if err != nil {
306					return nil, err
307				}
308			} else {
309				validSize, snapshotCount, err = replayWAL(dir, apply)
310				if err != nil {
311					return nil, err
312				}
313			}
314		}
315	
316		wal, err := openWALWriter(dir, validSize)
317		if err != nil {
318			return nil, err
319		}
320	
321		s := &Store{
322			dir:        dir,
323			wal:        wal,
324			cursors:    make(map[*Cursor]struct{}),
325			nextSeq:    replaySeq,
326			chain:      chain,
327			dirty:      dedupeKeys(nil, tailTouched),
328			legacyLive: legacyLive,
329		}
330		s.snapshots.Store(snapshotCount)
331		s.current.Store(latest)
332		return s, nil
333	}
334	
335	// dedupeKeys returns app's distinct keys appended to dst, first occurrence
336	// wins, preserving order.
337	func dedupeKeys(dst, src []string) []string {
338		seen := make(map[string]struct{}, len(src))
339		out := dst
340		for _, k := range src {
341			if _, ok := seen[k]; ok {
342				continue
343			}
344			seen[k] = struct{}{}
345			out = append(out, k)
346		}
347		return out
348	}
349	
350	// Put stores value under key. An empty key returns an error wrapping
351	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
352	// key reports a hit. The store does not keep a reference to value.
353	//
354	// Put is exactly a one-op batch: it joins the same group-commit queue as
355	// CommitBatch, so a single write and concurrent batches can share one disk
356	// sync while each keeps its own crash atomicity.
357	func (s *Store) Put(key string, value []byte) error {
358		if s.closed.Load() {
359			return errStoreClosed
360		}
361		if key == "" {
362			return errEmptyKey
363		}
364		return s.commit([]BatchOp{{Key: key, Value: value}})
365	}
366	
367	// Delete removes key. Deleting an empty key returns an error wrapping
368	// fs.ErrInvalid; deleting a key that was never written or is already deleted
369	// is not an error and commits nothing. It joins the same group-commit queue a
370	// batch uses.
371	func (s *Store) Delete(key string) error {
372		if s.closed.Load() {
373			return errStoreClosed
374		}
375		if key == "" {
376			return errEmptyKey
377		}
378		return s.commit([]BatchOp{{Key: key, Delete: true}})
379	}
380	
381	type pendingBatch struct {
382		ops  []BatchOp
383		done chan error // buffered(1); the leader delivers the commit result
384	}
385	
386	// commitPlan is one queued batch resolved against the cumulative state built
387	// up across its whole sync group.
388	type commitPlan struct {
389		view  *view // cumulative view after this batch; nil when it committed nothing
390		dirty []string
391	}
392	
393	// BatchOp is one change in a batch committed with CommitBatch. Delete false
394	// stores Value under Key (a nil or empty Value is still a hit); Delete true
395	// removes Key.
396	type BatchOp struct {
397		Key    string
398		Value  []byte
399		Delete bool
400	}
401	
402	// commit enqueues ops as one atomic framed commit and drives the leader loop.
403	// Single-key Put/Delete and CommitBatch are all this one path.
404	func (s *Store) commit(ops []BatchOp) error {
405		if s.closed.Load() {
406			return errStoreClosed
407		}
408		if err := validateBatchOps(ops); err != nil {
409			return err
410		}
411	
412		me := &pendingBatch{ops: ops, done: make(chan error, 1)}
413	
414		// Enqueue. queueMu guards only the queue and the leader flag and is
415		// never held across disk I/O, so followers can join a group while the
416		// leader is syncing and readers never wait.
417		s.queueMu.Lock()
418		if s.closed.Load() {
419			s.queueMu.Unlock()
420			return errStoreClosed
421		}
422		s.queue = append(s.queue, me)
423		if s.committer {
424			s.queueMu.Unlock()
425			return <-me.done // the running leader will drain this batch
426		}
427		s.committer = true
428		s.queueMu.Unlock()
429	
430		// Test-only rendezvous: invoked once by the elected leader before its
431		// first queue drain. Production leaves it nil.
432		if s.leaderHook != nil {
433			s.leaderHook()
434		}
435	
436		// Leadership: drain groups until the queue is empty. Each group takes
437		// s.mu while it forces the log, which serializes it with Snapshot,
438		// Checkpoint, Compact and Close, so a group never straddles a log swap or
439		// a layer capture.
440		for {
441			s.queueMu.Lock()
442			// Resign and re-check the queue under one critical section, so a
443			// batch enqueuing in this instant either observes the still-active
444			// leader or becomes the next one; no batch can be left queued with
445			// no leader to drain it.
446			if len(s.queue) == 0 {
447				s.committer = false
448				s.queueMu.Unlock()
449				break
450			}
451			group := s.queue
452			s.queue = nil
453			s.queueMu.Unlock()
454			for p, rerr := range s.commitGroup(group) {
455				group[p].done <- rerr
456			}
457		}
458	
459		return <-me.done
460	}
461	
462	// CommitBatch applies a group of writes and deletes as one atomic commit:
463	// the whole batch becomes visible together or not at all, and snapshots and
464	// cursors fixed at any instant see either the state before the batch or the
465	// state after it, never an in-between mixture. Changes are applied in list
466	// order; a later change to the same key overrides an earlier one within the
467	// batch. Concurrent batches take effect in commit (enqueue) order, and a
468	// later committed batch's same-key change overrides an earlier one's.
469	//
470	// Batches committed concurrently (with single Put/Delete calls among them)
471	// share the disk sync: one leader drains the queue, encodes every waiting
472	// commit as its own recoverable framed commit and forces them all with one
473	// flush plus fsync, so N commits arriving together cost one sync while each
474	// stays whole on recovery; a commit that arrives while a sync is in flight
475	// rides the next one. Reads take none of these locks and are never blocked by
476	// the sync.
477	//
478	// If any change has an empty key the whole batch is rejected before it is
479	// queued or committed: an error wrapping fs.ErrInvalid is returned, no frame
480	// is written and the store's state is unchanged. A delete of a key that is
481	// absent or already deleted commits nothing, exactly like Delete; a batch
482	// containing only such no-ops (or an empty slice) commits nothing and
483	// returns nil. CommitBatch on a closed store returns an error wrapping
484	// fs.ErrClosed.
485	//
486	// Each batch is forced to stable storage before its call returns and is
487	// published as one new view; a process killed mid-commit therefore reopens
488	// with the entire batch present or entirely absent. The store does not keep
489	// references to the op Value slices after return.
490	func (s *Store) CommitBatch(ops []BatchOp) error {
491		return s.commit(ops)
492	}
493	
494	// validateBatchOps checks argument-only invariants before a batch is queued.
495	// Empty keys map to fs.ErrInvalid, exactly as for Put and Delete.
496	func validateBatchOps(ops []BatchOp) error {
497		for i := range ops {
498			if ops[i].Key == "" {
499				return errEmptyKey
500			}
501		}
502		for i := range ops {
503			if len(ops[i].Key) > maxRecord || (!ops[i].Delete && seqSize+len(ops[i].Value) > maxRecord) {
504				return errRecordTooLarge()
505			}
506		}
507		return nil
508	}
509	
510	func errRecordTooLarge() error { return errors.New("snapshot: record too large") }
511	
512	// commitGroup encodes and forces every queued batch with one flush and one
513	// sync, then publishes one view per effective batch in queue (commit) order.
514	// It returns one result per batch. An encoding or sync failure fails the
515	// whole group: nothing it contained is published or sequenced. The single
516	// committer calls this; s.mu is taken for the entire force, exactly as the
517	// view transitions and checkpoint watermarks need.
518	func (s *Store) commitGroup(group []*pendingBatch) []error {
519		results := make([]error, len(group))
520	
521		s.mu.Lock()
522		defer s.mu.Unlock()
523		if s.closed.Load() || s.wal == nil {
524			// Close ran between the drain and the lock; nothing can commit.
525			for i := range results {
526				results[i] = errStoreClosed
527			}
528			return results
529		}
530	
531		// Remember where the group starts so any failure can rewind the log:
532		// unacknowledged frames must not linger at EOF and reappear under a
533		// later commit or after a reopen. Nothing is buffered here (the previous
534		// group always flushed), so EOF is the exact offset.
535		groupStart, posErr := s.wal.position()
536		if posErr != nil {
537			for i := range results {
538				results[i] = posErr
539			}
540			return results
541		}
542		rollback := func(cause error) []error {
543			if err := s.wal.truncateTo(groupStart); err != nil {
544				cause = errors.Join(cause, err)
545			}
546			for i := range results {
547				results[i] = cause
548			}
549			return results
550		}
551	
552		base := s.current.Load()
553		seq := s.nextSeq
554		plans := make([]commitPlan, 0, len(group))
555		encodedAny := false
556		var groupDirty []string
557	
558		// head caches the group-cumulative terminal node of every key the queued
559		// batches touch: a nil entry means "known absent in base". It is sized by
560		// the batches' distinct keys, never by the live keyspace. The baseline
561		// flattened the whole view inside this loop every viewFlattenLimit queued
562		// batches, so a long queue behind one sync copied the live keyspace once
563		// per viewFlattenLimit batches; now each touched key walks the (already
564		// bounded) overlay chain at most once and at most one full keyspace map is
565		// built per group, after the last overlay.
566		head := make(map[string]*node)
567		resolve := func(key string) *node {
568			if n, ok := head[key]; ok {
569				return n // nil records a key known to be absent
570			}
571			n := base.lookup(key)
572			head[key] = n
573			return n
574		}
575	
576		for _, p := range group {
577			// Each batch gets its own thin immutable overlay on the previous
578			// batch's overlay, so the view it publishes is a valid point-in-time
579			// state independent of later batches, and queued batches cost memory
580			// proportional to their own ops rather than the whole live keyspace.
581			v := newView(base)
582			var changes []batchChange
583			for i := range p.ops {
584				op := &p.ops[i]
585				headNode := resolve(op.Key)
586				if op.Delete {
587					if headNode == nil || !headNode.present {
588						continue // idempotent no-op, matching the single Delete
589					}
590					seq++
591					nn := &node{present: false, seq: seq, older: headNode}
592					changes = append(changes, batchChange{key: op.Key, seq: seq, delete: true})
593					v.keys[op.Key] = nn
594					head[op.Key] = nn
595				} else {
596					seq++
597					value := cloneBytes(op.Value)
598					nn := &node{value: value, present: true, seq: seq, older: headNode}
599					changes = append(changes, batchChange{key: op.Key, seq: seq, value: value})
600					v.keys[op.Key] = nn
601					head[op.Key] = nn
602				}
603			}
604			if len(changes) > 0 {
605				if err := s.wal.encodeBatch(changes); err != nil {
606					return rollback(err)
607				}
608				encodedAny = true
609				for i := range changes {
610					groupDirty = append(groupDirty, changes[i].key)
611				}
612			}
613			var planView *view
614			if len(changes) > 0 {
615				planView = v
616			}
617			plans = append(plans, commitPlan{view: planView})
618			base = v
619		}
620	
621		if encodedAny {
622			// One flush, one fsync for the whole group. Return means every
623			// encoded batch in it is durable as a self-contained framed commit.
624			if err := s.wal.flushSync(); err != nil {
625				return rollback(err)
626			}
627		}
628	
629		s.nextSeq = seq
630		// Publish one view per effective batch in queue order, so each batch's
631		// state becomes observable atomically as its own point-in-time view. Then,
632		// whenever the chain reached the depth bound, publish one flattened final
633		// view. That flatten builds one full keyspace map at most (after the last
634		// overlay) and keeps read depth and the next group's baseline bounded by
635		// viewFlattenLimit rather than by queue length; the baseline built one full
636		// map per viewFlattenLimit queued batches inside the loop.
637		var finalFlat *view
638		if base.depth >= viewFlattenLimit {
639			finalFlat = base.flatten()
640		}
641		for _, plan := range plans {
642			if plan.view != nil {
643				s.current.Store(plan.view)
644			}
645		}
646		if finalFlat != nil {
647			s.current.Store(finalFlat)
648		}
649		s.dirty = dedupeKeys(s.dirty, groupDirty)
650		return results
651	}
652	
653	// Get returns the latest committed value for key. Empty keys, keys never
654	// written and deleted keys are all misses: ok is false and err is nil. The
655	// returned bytes are owned by the caller.
656	func (s *Store) Get(key string) ([]byte, bool, error) {
657		if s.closed.Load() {
658			return nil, false, errStoreClosed
659		}
660		if key == "" {
661			return nil, false, nil
662		}
663		val, ok := lookupView(s.current.Load(), key)
664		return val, ok, nil
665	}
666	
667	// Compact reclaims history: values that were overwritten or deleted and are
668	// not needed by any open snapshot or cursor are dropped from memory and the
669	// write-ahead log is atomically rewritten, so the directory occupies less
670	// space than before whenever reclaimable history existed.
671	//
672	// When a checkpoint chain is live, compaction keeps the generations inside
673	// the retention window and re-anchors them against the replacement log: that
674	// log is written as one segment per surviving layer (its prefix reproducing
675	// the layer's terminal state at a fresh cut), followed by the post-window
676	// changes and the snapshot-count meta, and the rebuilt layers reference those
677	// cuts. Generations outside the window are retired together with the old
678	// chain and stop occupying space immediately.
679	//
680	// Every open snapshot keeps its exact fixed view; every open cursor keeps
681	// paging through its exact fixed sequence, and the one version per key its
682	// view shows stays in the rewritten log until the cursor closes; the next
683	// compaction then reclaims it and shrinks the directory further. A process
684	// killed at any point during compaction reopens in a complete commit state,
685	// with every successful write, deletion and the cumulative snapshot count
686	// intact; no intermediate file needs a second compaction or checkpoint to
687	// repair.
688	//
689	// Compact serializes with writes, deletes, snapshots, cursor opens, closing
690	// and other compactions (the group-commit leader and every other mutator
691	// take the same lock); concurrent or repeated calls queue and all return nil.
692	// Compacting a closed store returns an error wrapping fs.ErrClosed.
693	func (s *Store) Compact() error {
694		s.mu.Lock()
695		defer s.mu.Unlock()
696		if s.closed.Load() {
697			return errStoreClosed
698		}
699	
700		cur := s.current.Load()
701	
702		// Pinned versions, keyed by commit sequence (globally unique). The
703		// current head of every live key in the latest view is retained; each
704		// open cursor additionally pins the single head version its fixed view
705		// shows for every present key in its range. A deleted key's tombstone is
706		// retained only when a cursor still reads an older value under it, so
707		// replay links that value as the tombstone's predecessor; otherwise the
708		// key is dropped from the rewritten log altogether, as before.
709		pinned := make(map[uint64]*node)
710		keySeqs := make(map[string][]uint64)
711		cursorPins := make(map[string]bool)
712		pin := func(k string, n *node) {
713			if n == nil {
714				return
715			}
716			if _, ok := pinned[n.seq]; !ok {
717				pinned[n.seq] = n
718				keySeqs[k] = append(keySeqs[k], n.seq)
719			}
720		}
721		for _, c := range s.openCursors() {
722			for _, k := range c.keys {
723				cursorPins[k] = true
724				pin(k, c.v.lookup(k)) // exactly the version this cursor pages out
725			}
726		}
727		for k, n := range keySetOf(cur) {
728			if n.present || cursorPins[k] {
729				pin(k, n) // live head, or a tombstone shielding a pinned value
730			}
731		}
732	
733		plan := buildCompactionPlan(pinned, keySeqs)
734		snapshotCount := s.snapshots.Load()
735	
736		// The surviving window, oldest first. Layers before it are retired.
737		window := checkpointWindow
738		if window > len(s.chain) {
739			window = len(s.chain)
740		}
741		first := len(s.chain) - window
742		windowLayers := s.chain[first:]
743		hadChain := len(s.chain) > 0
744		// paired reports any checkpoint — layered chain or a legacy single file —
745		// whose cut belongs to the WAL about to be replaced. It must be withdrawn
746		// before the swap so no checkpoint is ever read against a different log.
747		paired := hadChain || s.legacyLive
748	
749		// Phase 1 (nothing live is touched yet): build and sync the complete
750		// replacement log, and when layers survive, the matching staged chain.
751		// Any failure here removes the staged files and leaves the store and the
752		// old WAL/chain exactly as they were, so committing can continue.
753		var seg *segmentedWAL
754		if !hadChain {
755			if err := buildCompactWAL(s.dir, plan.histories(), snapshotCount); err != nil {
756				return err
757			}
758		} else {
759			// Full terminal state at each window layer's watermark, composed from
760			// the complete old chain (including the generations about to retire).
761			termStates := make([][]checkpointEntry, window)
762			for w := 0; w < window; w++ {
763				termStates[w] = composeLayers(s.chain[:first+w+1])
764			}
765			seg = planSegmentedWAL(plan, windowLayers, termStates, cur)
766			if err := buildSegmentedCompactArtifacts(s.dir, seg, snapshotCount); err != nil {
767				return err
768			}
769		}
770	
771		// Phase 2: the replacement must never meet a paired checkpoint on reopen.
772		// Durably withdraw the whole layered chain and/or the legacy file while
773		// the old wal.log is still in place; a crash after this but before the
774		// rename simply replays the old log in full. Failure precedes any
775		// stateful move, so drop the staged files and leave the store untouched.
776		if paired {
777			if err := retireChain(s.dir); err != nil {
778				removeStaleCompact(s.dir)
779				removeStagedChain(s.dir)
780				return err
781			}
782			s.legacyLive = false
783		}
784		oldWAL := s.wal
785		if err := oldWAL.close(); err != nil {
786			// Staged files have not become state of record; remove them and
787			// reopen a writer on the untouched old log, so no repair-only
788			// intermediate lingers and the next commit proceeds.
789			removeStaleCompact(s.dir)
790			removeStagedChain(s.dir)
791			reopened, openErr := openWALWriter(s.dir, -1)
792			if openErr != nil {
793				return err
794			}
795			s.wal = reopened
796			return err
797		}
798		// Phase 3: atomically rename the temp over wal.log, force the directory
799		// and open a writer on the new log. If the rename never landed the old
800		// log is intact and committing continues (staged chain is dropped).
801		nextWAL, renamed, installErr := installCompactWAL(s.dir)
802		if nextWAL == nil {
803			// The rename landed but the new log cannot be opened: the directory
804			// is not in a state where further commits are safe, so mark the
805			// store closed rather than leaving a handle only another compaction
806			// could repair.
807			s.closed.Store(true)
808			s.wal = nil
809			return installErr
810		}
811		s.wal = nextWAL
812		if renamed {
813			s.current.Store(plan.freshView())
814			if hadChain {
815				// dropCheckpoint clears any in-memory and on-disk chain so the
816				// next Checkpoint starts a fresh base with no O_EXCL collision.
817				dropCheckpoint := func() {
818					s.chain = nil
819					s.dirty = nil
820					os.RemoveAll(checkpointDirPath(s.dir))
821				}
822				if window == 0 {
823					dropCheckpoint()
824					removeStagedChain(s.dir)
825				} else if err := activateStagedChain(s.dir); err != nil {
826					// The new WAL is already live; rather than leave a half
827					// installed chain, run with no live checkpoint. The next
828					// Checkpoint establishes a fresh base.
829					dropCheckpoint()
830				} else {
831					info, ierr := readChain(s.dir)
832					if ierr != nil || len(info.layers) != window {
833						dropCheckpoint()
834					} else {
835						s.chain = info.layers
836						s.dirty = seg.tailKeys
837					}
838				}
839			}
840		} else if hadChain {
841			// Rename failed; the old WAL stayed. retireChain already removed the
842			// old chain, so drop the staged replacement as well: no checkpoint
843			// pairs with this WAL. Committing continues; the next Checkpoint heals.
844			removeStagedChain(s.dir)
845			s.chain = nil
846			s.dirty = nil
847		}
848		return installErr
849	}
