package snapshot

import (
	"bufio"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strconv"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

// Cross-object coordination of one backup chain directory.
//
// Several storage objects (separate Stores, separate processes) can share one
// chain directory. The operations that reshape a chain — a full export that
// writes into it, an incremental ring append, a chain merge, and a restore
// that reads it for synthesis — must be mutually exclusive: at any instant the
// chain is either exactly the chain before the operation or the complete chain
// after it, never anything in between.
//
// Coordination lives in a small "chain.lock" file inside the chain directory:
//
//   - Liveness is the file's write lock (an open-file-description lock on
//     Linux via F_OFD_SETLK): the holder keeps the file open and write-locked
//     for the whole operation. A process killed with the operation in flight
//     releases the lock automatically as its file descriptors close, so no
//     operation can stay mutually excluded forever. There is no heartbeat and
//     no stale-lock cleanup needed just to detect a dead holder.
//   - The file body names the holder (process id plus a per-process unique
//     token), the operation kind and the lease deadline, a little-endian
//     record followed by an IEEE CRC-32. The deadline is a secondary safety
//     margin for environments that do not release byte-range locks on process
//     death (some network filesystems): a lease whose deadline has passed is
//     reclaimable even while its lock looks held.
//
// Acquiring never waits: if another live holder owns the chain the whole
// request fails immediately with an error wrapping fs.ErrInvalid. The holder
// renews the deadline in the background so a long streaming export or merge
// never has a valid operation mistaken for a dead one. The lock file is
// removed when the operation finishes.
//
// A kill at any instant leaves either the old chain or the complete new chain.
// A leftover lock file from a killed holder is reclaimed at the next backup,
// incremental export, merge or restore into that directory, and at the next
// Open of the directory (or of a related sibling), after which the chain is
// usable again with no manual cleanup.

const (
	chainLockName = "chain.lock"

	// chainLeaseTTL is how long a held lease stays valid without a renewal.
	// The holder renews well inside it; only a killed holder ever lets it
	// lapse, and only on filesystems that do not drop byte-range locks on
	// process death does the deadline actually decide liveness.
	chainLeaseTTL = 30 * time.Second
	// chainLeaseRenew is the renewal interval while an operation holds a
	// lease. It is well under the TTL so a couple of slow scheduling moments
	// never expire a live lease.
	chainLeaseRenew = chainLeaseTTL / 3

	// chainLockBodySize is holder(8) + op(1) + deadlineUnixNano(8) + deadlineAddNs(8) + crc(4).
	chainLockBodySize = 8 + 1 + 8 + 8 + 4
)

// errChainBusy reports that another registered operation currently holds the
// chain. The rejected request changes nothing and the error satisfies
