			info, serr := f.Stat()
			if serr != nil {
				return false, serr
			}
			return chainTime().Sub(info.ModTime()) > chainLeaseTTL, nil
		}
		return false, err
	}
	// No trailing bytes: the record has exactly one fixed size.
	if extra, rerr := r.ReadByte(); !errors.Is(rerr, io.EOF) || extra != 0 {
		return false, nil
	}
	if binary.LittleEndian.Uint32(body[25:29]) != crc32IEEE(body[:25]) {
		return false, nil
	}
	deadline := time.Unix(
		int64(binary.LittleEndian.Uint64(body[9:17])),
		int64(binary.LittleEndian.Uint64(body[17:25])),
	)
	return chainTime().After(deadline), nil
}

// crc32IEEE is a tiny local CRC helper so lease.go stands alone; the backup
// code's crc32 tables are reused indirectly through hash/crc32.
func crc32IEEE(b []byte) uint32 {
	return crc32Update(b)
}

// reclaimChainLease clears a lock file that no operation can hold any more —
// one left by a killed holder when there is no competing descriptor. It is
// used by open-time sweep paths, which never take a lease themselves. Nothing
// is removed unless the file is absent, stale, or unlockable; a live holder's
// file is left untouched.
func reclaimChainLease(dir string) {
	path := filepath.Join(dir, chainLockName)
	f, err := os.OpenFile(path, os.O_RDWR, 0)
	if err != nil {
		return // absent or unreadable: nothing to reclaim
	}
	conn, err := newSyscallConn(f)
	if err != nil {
		f.Close()
		return
	}
	held, err := conn.tryWriteLock()
	if err != nil {
		f.Close()
		return
	}
	remove := held
	if !held {
		stale, serr := staleChainLease(path)
		if serr != nil {
			f.Close()
			return
		}
		remove = stale
	}
	f.Close()
	if remove {
		if err := os.Remove(path); err == nil {
			_ = syncDirectory(dir)
		}
