	m, _ := chainLeases.LoadOrStore(absDir, &sync.Mutex{})
	return m.(*sync.Mutex)
}

func absPathOrSelf(p string) string {
	abs, err := filepath.Abs(p)
	if err != nil {
		return p
	}
	return abs
}

