		// only when its record says its deadline has passed; otherwise the
		// request fails busy without touching the holder's file.
		stale, serr := chainLeaseRecordStale(path)
		if serr != nil || !stale || attempt > 0 {
			opened.Close()
			if serr != nil {
				return nil, serr
			}
			return nil, errChainBusy
		}
		// Fence the expired holder: its lock stays on the old inode, so drop
		// the name and create a fresh one to lock.
		opened.Close()
		if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}
		_ = syncDirectory(dir)
	}

