		dir:   dir,
		path:  path,
		file:  f,
		op:    op,
		token: nextLeaseToken(),
		stop:  make(chan struct{}),
		done:  make(chan struct{}),
	}
	if err := l.rewriteRecord(chainTime().Add(chainLeaseTTL)); err != nil {
		l.drop()
		return nil, err
	}
	if err := f.Sync(); err != nil {
		l.drop()
		return nil, err
	}
	go l.renewLoop()
	return l, nil
}

// adoptStageLock acquires the same write lease under chainLockName inside a
// merge's staged sibling directory before the commit renames. The lock then
// moves onto the chain path with the staged directory, so the chain is locked
// continuously across the swap rather than only on the old chain's inode.
func (l *chainLease) adoptStageLock(stage string) error {
	path := filepath.Join(stage, chainLockName)
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	held, err := tryOFDWriteLock(f)
	if err != nil {
		f.Close()
