func acquireChainLease(dir string, op byte) (*chainLease, error) {
	path := filepath.Join(dir, chainLockName)

	var f *os.File
	for attempt := 0; ; attempt++ {
		opened, oerr := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
		if oerr != nil {
