// release ends coordination: it stops renewal, removes the live lock file(s)
// while still holding their locks, forces the directory and closes the
// descriptors. Removal-before-close means a concurrent acquirer never
// observes a chain unlocked while a replacement record is half-written. It is
// idempotent.
func (l *chainLease) release() {
	if l == nil {
		return
	}
	select {
	case <-l.stop:
		return
	default:
		close(l.stop)
	}
	<-l.done
	if l.stageFile != nil {
		// After the swap stagePath is the live chain lock; remove it by its
		// current name. The old lock's directory is the trash sibling (or
		// already gone).
		_ = os.Remove(l.stagePath)
		if l.stage != "" {
			_ = syncDirectory(l.stage)
		}
		_ = l.stageFile.Close()
		l.stageFile = nil
	}
	if l.file != nil {
		_ = os.Remove(l.path)
		_ = syncDirectory(l.dir)
		_ = l.file.Close()
		l.file = nil
	}
}

