// filesystem that retained its byte-range lock: the file is present with a
// deadline in the past. The next acquisition must fence it and proceed.
func TestChainLeaseReclaimsExpiredHolder(t *testing.T) {
	dir := t.TempDir()

	holder, err := acquireChainLease(dir, chainOpMerge)
	if err != nil {
		t.Fatal(err)
	}
	// Plant an expired record while the holder's file exists, then close it
	// without removing the file: the lock is free and the record is stale.
	expired := encodeLeaseRecord(holder.token, chainOpMerge, chainTime().Add(-time.Second))
	if err := os.WriteFile(filepath.Join(dir, chainLockName), expired, 0o600); err != nil {
		t.Fatal(err)
	}
	holder.release() // removes nothing now (WriteFile replaced the name), closes fd
	if err := os.WriteFile(filepath.Join(dir, chainLockName), expired, 0o600); err != nil {
		t.Fatal(err)
	}

	next, err := acquireChainLease(dir, chainOpIncremental)
	if err != nil {
		t.Fatalf("acquire over expired holder = %v, want reclaimed lease", err)
	}
	next.release()
}

