func (s *Store) BackupIncremental(chainDir string) error {
	if s.closed.Load() {
		return errStoreClosed
	}
	if chainDir == "" {
		return errBadBackup
	}
	// Repair or clear debris from a merge killed mid-commit before inspecting
	// the chain.
