	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return errBadBackup
		}
		return err
	}
	if !info.IsDir() {
		return errBadBackup
	}
	// Register this export on the chain directory. A concurrent full export,
	// incremental export, merge or restore on the same chain fails wholesale
	// with fs.ErrInvalid rather than sharing the staging directory or racing
	// the next ring index. The lease is independent of s.mu: it spans the
	// export's disk I/O and never blocks commits or lock-free reads.
	lease, err := acquireChainLease(chainDir, chainOpIncremental)
	if err != nil {
		return err
	}
	defer lease.release()
	if s.closed.Load() {
		return errStoreClosed
	}
	// Clear staging debris from an export (full or incremental) killed mid-run
	// before inspecting the chain; a manifest temp is pure debris as well.
	for _, stage := range []string{incrStageDir, backupStageDir} {
		if err := os.RemoveAll(filepath.Join(chainDir, stage)); err != nil {
			return err
		}
	}

