package snapshot

import (
	"errors"
	"fmt"
	"io/fs"
	"path/filepath"
	"sync"
	"testing"
)

func TestDebugStorm3(t *testing.T) {
	bad := 0
	for iter := 0; iter < 40; iter++ {
		parent := t.TempDir()
		chain := filepath.Join(parent, "chain")
		s, _ := Open(filepath.Join(parent, "store"))
		s.Backup(chain)
		for i := 0; i < 4; i++ { s.Put(fmt.Sprintf("k%d", i), []byte("v")); s.Snapshot(); s.BackupIncremental(chain) }
		var wg sync.WaitGroup
		start := make(chan struct{})
		var ok, busy, other int
		for g := 0; g < 24; g++ {
			wg.Add(1)
			go func(g int) {
				defer wg.Done()
				<-start
				var rerr error
				target := filepath.Join(parent, fmt.Sprintf("target-%d", g))
				switch g % 3 {
				case 0: rerr = s.MergeChain(chain, 1)
				case 1: rerr = s.BackupIncremental(chain)
				default: _, rerr = Restore(chain, target)
				}
				switch {
				case rerr == nil: ok++
				case errors.Is(rerr, fs.ErrInvalid): busy++
				default: other++; fmt.Printf("iter%d g=%d OTHER: %v\n", iter, g, rerr)
				}
			}(g)
		}
		close(start); wg.Wait()
		if ok == 0 {
			bad++
			fmt.Printf("iter%d ZERO ok busy=%d other=%d\n", iter, busy, other)
		}
		if _, verr := validateBackupChain(chain); verr != nil {
			t.Fatalf("iter%d chain invalid: %v", iter, verr)
		}
		s.Close()
	}
	if bad > 0 { t.Fatalf("%d zero-winner iterations", bad) }
}
EOF
